def is_enabled(service):
    return run(["systemctl", "is-enabled", "--quiet", service]).returncode == 0

def last_logs(service, lines=20):
    return run(["journalctl", "-u", service, "-n", str(lines), "--no-pager"]).stdout

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("services", nargs="+")
    ap.add_argument("--restart", action="store_true", help="attempt to restart failed services")
    args = ap.parse_args()

    failed = []
    for svc in args.services:
        if is_active(svc):
            log.info(f"OK      {svc} (enabled={is_enabled(svc)})")
            continue

        log.error(f"DOWN    {svc}")
        log.error("last log lines:\n" + last_logs(svc))
        failed.append(svc)

        if args.restart:
            log.warning(f"restarting {svc}")
            r = run(["systemctl", "restart", svc], timeout=60)
            if r.returncode == 0 and is_active(svc):
                log.info(f"RECOVERED {svc}")
                failed.remove(svc)
            else:
                log.error(f"restart failed for {svc}: {r.stderr.strip()}")

    sys.exit(1 if failed else 0)

if __name__ == "__main__":
    main()
AUTO-RESTART WITHOUT A LIMIT IS DANGEROUS
A script that restarts a service every time it finds it down will happily restart a crashing service every minute forever,
hiding the real problem and possibly amplifying it - a service that crashes under load will crash faster when restarted
repeatedly. If you automate restarts, cap the attempts, back off between them, and always raise an alert so a human
knows it happened. Restarting is mitigation, not a fix.
14.10 Script 9 - Composite Health Check
healthcheck.py
 #!/usr/bin/env python3
"""Run all checks and emit a JSON summary suitable for a pipeline or a dashboard."""
import sys, json, socket, shutil, subprocess, urllib.request, urllib.error
from datetime import datetime, timezone

def check_disk(path="/", threshold=85):
    total, used, _ = shutil.disk_usage(path)
    pct = used / total * 100
    return {"name": f"disk:{path}", "value": round(pct, 1),
            "ok": pct < threshold, "detail": f"{pct:.1f}% used"}

def check_memory(threshold=90):
    info = {}
    with open("/proc/meminfo") as f:
        for line in f:
            k, v = line.split(":", 1)
            info[k] = int(v.split()[0])
    pct = (info["MemTotal"] - info["MemAvailable"]) / info["MemTotal"] * 100
    return {"name": "memory", "value": round(pct, 1),
            "ok": pct < threshold, "detail": f"{pct:.1f}% used"}

