def check_service(name):
    rc = subprocess.run(["systemctl", "is-active", "--quiet", name]).returncode
    return {"name": f"service:{name}", "value": rc, "ok": rc == 0,
            "detail": "active" if rc == 0 else "inactive"}

def check_port(host, port, timeout=3):
    s = socket.socket(); s.settimeout(timeout)
    try:
        s.connect((host, port)); ok, detail = True, "open"
    except ConnectionRefusedError:
        ok, detail = False, "refused"
    except Exception as e:
        ok, detail = False, type(e).__name__
    finally:
        s.close()
    return {"name": f"port:{host}:{port}", "value": None, "ok": ok, "detail": detail}

def check_http(url, expect=200, timeout=5):
    try:
        with urllib.request.urlopen(url, timeout=timeout) as r:
            ok = r.status == expect
            return {"name": f"http:{url}", "value": r.status, "ok": ok,
                    "detail": f"HTTP {r.status}"}
    except urllib.error.HTTPError as e:
        return {"name": f"http:{url}", "value": e.code, "ok": False, "detail": f"HTTP {e.code}"}
    except Exception as e:
        return {"name": f"http:{url}", "value": None, "ok": False, "detail": type(e).__name__}

def main():
    checks = [
        check_disk("/"),
        check_disk("/var"),
        check_memory(),
        check_service("nginx"),
        check_service("docker"),
        check_port("127.0.0.1", 8080),
        check_http("http://127.0.0.1:8080/health"),
    ]

    failed = [c for c in checks if not c["ok"]]
    report = {
        "host": socket.gethostname(),
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "status": "healthy" if not failed else "unhealthy",
        "failed_count": len(failed),
        "checks": checks,
    }

    print(json.dumps(report, indent=2))
    sys.exit(0 if not failed else 1)

if __name__ == "__main__":
    main()
WHY JSON OUTPUT MATTERS
Emitting JSON means the same script serves a human reading the terminal, a pipeline step checking the exit code, and
a monitoring system parsing the fields - without three different scripts. Combined with a non-zero exit on failure, it
drops straight into Jenkins, a cron job, or a Kubernetes readiness command.
14.11 Python Interview Questions
Q. 1. Why use Python for DevOps rather than Bash?
 Bash is better for short command orchestration - piping tools together, a few conditionals. Python takes over when there is
real logic: parsing structured data such as JSON or CSV, calling APIs, error handling with different behaviour per failure type,
or anything longer than about fifty lines. Python is also far more readable and testable when someone else has to maintain
it at 3am.
